  const BOX=[12,58,180,246],GRAB=14,TAUT=.85,SNAPT=3,RETIE=.8,HOLD=5,B=330;
  /* what each home needs (0 light, 1 quiet, 2 company, 3 warmth), at the start of Stage I and at the end of each stage's changes */
  const NEED0=[2,0,2,0,3,3,1,1];
  const NEEDS=[[2,0,2,0,3,3,1,1],[2,0,2,0,3,1,2,1],[3,0,3,0,1,3,2,1]];
  const FLIPS=[[],[[1.5,5,1],[3,6,2]],[[.6,0,3],[.9,2,3],[1.2,4,1],[1.5,5,3]]];   /* [seconds into the stage, home, new need] */
  const R=[[75,86,83,85],[75,91,112,85],[75,88,60,160]];                           /* reach, per stage, per knot (light, quiet, company, warmth) */
  const START=[[80,170],[92,124],[112,152],[130,130]];                              /* Stage I: a loose cluster in the courtyard, every home out of reach */
  const SOL=[[[117,108],[101,144],[111,70],[67,146]],[[117,108],[83,144],[100,115],[67,146]],[[117,108],[83,144],[110,173],[96,84]]];   /* the stored solutions (knot x,y per stage) */
  const SAY2="Needs change. The baby’s asleep now, and the old man is awake. Keep watching.";
  const COL={t:"#E8B860",taut:"#FFF1C0",red:"#FF5A4A",loose:"#B8A070"};
  const px=(c,x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(hs(x),hs(y),w,h)};
  const rnd=(a,b)=>a+Math.random()*(b-a);
