    if(p.k==="cloud"){const r=p.r0+(p.r1-p.r0)*u;c.globalAlpha=Math.max(0,(1-u)*.4);c.fillStyle="#C4B49A";c.beginPath();c.ellipse(p.x,p.y,r,r*.62,0,0,7);c.fill();c.globalAlpha=Math.max(0,(1-u)*.25);c.fillStyle="#E8DCC4";c.beginPath();c.ellipse(p.x-r*.2,p.y-r*.2,r*.6,r*.36,0,0,7);c.fill()}
    else if(p.k==="dust"||p.k==="smoke"||p.k==="steam"){const r=Math.round(3+u*3);px(c,p.x-r,p.y-r/2,r*2,r,p.col||"#A89A8A");px(c,p.x-r+1,p.y-r/2-1,r*2-2,1,p.col||"#A89A8A")}
    else if(p.k==="wisp"){c.globalAlpha=Math.max(0,Math.min(1,u*5))*(1-u)*.34;c.fillStyle="#9C96A8";const r=2+u*5;c.beginPath();c.arc(p.x,p.y,r,0,7);c.fill()}
