    heart(c,x,y){px(c,x+1,y,2,2,"#E86A8A");px(c,x+4,y,2,2,"#E86A8A");px(c,x+1,y+1,5,2,"#E86A8A");px(c,x+2,y+3,3,1,"#E86A8A");px(c,x+3,y+4,1,1,"#E86A8A")},
